import React from "react";
import { Link } from "react-router-dom";

function Stars({ v }) {
  const n = Math.round(v || 0);
  return (
    <div style={{ display: "flex", gap: 4 }}>
      {Array.from({ length: 5 }).map((_, i) => (
        <span key={i} style={{ color: i < n ? "#f59e0b" : "#e6e7ea" }}>
          ★
        </span>
      ))}
    </div>
  );
}

export default function ProductCard({ product }) {
  const price = product.discount_price || product.price;
  const old = product.discount_price ? product.price : null;
  const discount = product.discount_price
    ? Math.round(100 - (product.discount_price / product.price) * 100)
    : 0;

  return (
    <div className="card card-wrap">
      {discount > 0 && <div className="badge">{discount}% OFF</div>}
      <Link
        to={`/product/${product.id}`}
        style={{ textDecoration: "none", color: "inherit" }}
      >
        <div
          style={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          <img
            src={product.images?.[0] || "/images/placeholder.png"}
            alt={product.name}
          />
        </div>
        <div className="meta">
          <h4>{product.name}</h4>
          <div style={{ textAlign: "right" }}>
            <div className="price">₹{price}</div>
            {old && <div className="old">₹{old}</div>}
          </div>
        </div>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginTop: 8,
          }}
        >
          <div
            style={{
              display: "flex",
              gap: 8,
              alignItems: "center",
            }}
          >
            <div className="rating">{Number(product.rating || 0).toFixed(1)}</div>
            <Stars v={product.rating} />
          </div>
          <div
            style={{
              fontSize: 12,
              color: "var(--muted)",
            }}
          >
            {product.reviews ? `${product.reviews} reviews` : ""}
          </div>
        </div>
      </Link>
    </div>
  );
}
